namespace sv_732c6cefdd5f43faa6100d29ba7cd036.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Holds the current theme state for a single circuit/user.
/// Registered as Scoped so each SignalR circuit gets its own instance.
/// </summary>
public sealed class ThemeService : IDisposable
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Mode or AccentColor changes.
    /// Subscribers (components) call StateHasChanged in response.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Apply multiple changes atomically (single notification).
    /// </summary>
    public void Update(ThemeMode mode, string accentColor)
    {
        bool changed = _mode != mode || _accentColor != accentColor;
        _mode = mode;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

@*
    Interactive wrapper that sits in MainLayout and cascades theme state
    to all descendants. Because this component has @rendermode InteractiveServer
    applied where it is used, it can subscribe to ThemeService change events
    and re-render the entire subtree reactively.
*@
@using sv_732c6cefdd5f43faa6100d29ba7cd036.Services
@inject ThemeService Theme
@implements IDisposable

<CascadingValue Value="Theme" IsFixed="false">
    @ChildContent
</CascadingValue>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@*
    Displays the current theme in the header bar.
    Receives ThemeService via CascadingParameter from ThemeProvider.
*@
@using sv_732c6cefdd5f43faa6100d29ba7cd036.Services

<span class="badge" style="background-color: @Theme.AccentColor; color: white;">
    🎨 @Theme.Mode
</span>

@code {
    [CascadingParameter] public ThemeService Theme { get; set; } = default!;
}

@*
    Quick toggle button that cycles Light → Dark → System.
    Can be placed anywhere (sidebar, header, any page).
*@
@using sv_732c6cefdd5f43faa6100d29ba7cd036.Services
@inject ThemeService Theme

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Current: @Theme.Mode — click to cycle">
    @GetIcon(Theme.Mode) @Theme.Mode
</button>

@code {
    private void CycleTheme()
    {
        Theme.Mode = Theme.Mode switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _ => ThemeMode.Light
        };
    }

    private static string GetIcon(ThemeMode mode) => mode switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _ => "☀️"
    };
}

@page "/settings"
@rendermode InteractiveServer
@using sv_732c6cefdd5f43faa6100d29ba7cd036.Services
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5>Theme Mode</h5>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(mode == selectedMode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => selectedMode = mode">
                @mode
            </button>
        }
    </div>

    <h5>Accent Color</h5>
    <input type="color" class="form-control form-control-color mb-3"
           @bind="selectedColor" @bind:event="oninput" />

    <button class="btn btn-success" @onclick="Save">Save Preferences</button>

    @if (saved)
    {
        <div class="alert alert-success mt-2 mb-0">Preferences saved!</div>
    }
</div>

@code {
    private ThemeMode selectedMode;
    private string selectedColor = "#0d6efd";
    private bool saved;

    protected override void OnInitialized()
    {
        selectedMode = Theme.Mode;
        selectedColor = Theme.AccentColor;
    }

    private void Save()
    {
        // Single atomic update — fires OnChange once
        Theme.Update(selectedMode, selectedColor);
        saved = true;
    }
}

